def run_lru(capacity, ops):
    # list of [key, value], front = least recently used
    cache = []
    def find(k):
        for i, (key, _) in enumerate(cache):
            if key == k:
                return i
        return -1
    out = []
    for op in ops:
        if op[0] == "put":
            _, k, v = op
            i = find(k)
            if i != -1:
                cache.pop(i)
            cache.append([k, v])
            if len(cache) > capacity:
                cache.pop(0)
        else:
            _, k = op
            i = find(k)
            if i == -1:
                out.append(-1)
            else:
                entry = cache.pop(i)
                cache.append(entry)
                out.append(entry[1])
    return out

