def count_parens(n):
    # backtracking enumeration, counting complete valid strings
    count = 0
    def build(open_used, close_used):
        nonlocal count
        if open_used == n and close_used == n:
            count += 1
            return
        if open_used < n:
            build(open_used + 1, close_used)
        if close_used < open_used:
            build(open_used, close_used + 1)
    build(0, 0)
    return count

